	SELECT *
      FROM (
         SELECT A.*, ROWNUM rn
      	   FROM (
        	  SELECT *
        		FROM QNA_TB
               WHERE qa_show = 'Y'


          		AND qa_writer_id = #{mbId}



                  AND (
                         qa_writer_id = #{mbId}
                      OR (mb_id = #{mbId} AND qa_answer IS NOT NULL)
          		       )


        		 ORDER BY qa_reg_date DESC
      			) A
      	WHERE ROWNUM <= #{end}
    	)
      WHERE rn >= #{start}

	SELECT COUNT(*) AS cnt
      FROM QNA_TB
     WHERE qa_show = 'Y'


        AND qa_writer_id = #{mbId}



        AND (
             qa_writer_id = #{mbId}
